create index journey_identity_time on public.journey_events(brand_id,anonymous_id,customer_id,occurred_at);
create index journey_refunds on public.journey_events(brand_id,order_id,currency,type);
create index metrics_post_time on public.entities(brand_id,(payload->>'postId'),created_at desc) where kind='metrics';
create or replace function public.period_attribution(p_brand uuid,p_start timestamptz,p_end timestamptz,p_days int default 30) returns jsonb language sql stable security definer set search_path=public as $$
 with purchases as(select * from resolved_events where brand_id=p_brand and type='purchase' and source<>'browser' and occurred_at>=p_start and occurred_at<p_end),
 touch_candidates as(select p.id purchase_id,t.channel,t.occurred_at,t.id from purchases p join resolved_events t on t.brand_id=p.brand_id and t.journey_id=p.journey_id and t.type in ('click','page_view','engaged','video_progress') and t.occurred_at<=p.occurred_at and t.occurred_at>=p.occurred_at-make_interval(days=>greatest(1,least(p_days,365))) and not exists(select 1 from resolved_events previous where previous.brand_id=p.brand_id and previous.journey_id=p.journey_id and previous.type='purchase' and previous.occurred_at<p.occurred_at and previous.occurred_at>=t.occurred_at)),
 channel_touches as(select purchase_id,channel,min(occurred_at) first_at,max(occurred_at) last_at from touch_candidates group by purchase_id,channel),
 touch as(select *,row_number() over(partition by purchase_id order by first_at,channel) first_n,row_number() over(partition by purchase_id order by last_at desc,channel) last_n,count(*) over(partition by purchase_id) n from channel_touches),
 net as(select p.id,p.currency,greatest(0,p.amount-coalesce((select sum(r.amount) from journey_events r where r.brand_id=p.brand_id and r.type='refund' and r.order_id=p.order_id and r.currency=p.currency and r.occurred_at<p_end),0)) amount from purchases p),
 allocated as(select t.channel,net.currency,sum(case when first_n=1 then net.amount else 0 end) first_touch,sum(case when last_n=1 then net.amount else 0 end) last_touch,sum(net.amount/t.n) linear from touch t join net on net.id=t.purchase_id group by t.channel,net.currency),
 unassigned as(select 'unattributed' channel,n.currency,sum(n.amount) first_touch,sum(n.amount) last_touch,sum(n.amount) linear from net n where not exists(select 1 from touch t where t.purchase_id=n.id) group by n.currency),
 first_purchases as(select customer_id,min(occurred_at) first_at from journey_events where brand_id=p_brand and type='purchase' and source<>'browser' and customer_id is not null group by customer_id),
 revenue as(select p.currency,count(*) purchases,count(distinct p.customer_id) customers,count(distinct p.customer_id) filter(where f.first_at>=p_start and f.first_at<p_end) new_customers,count(*) filter(where p.customer_id is null) anonymous_purchases,sum(net.amount) revenue from purchases p join net on net.id=p.id left join first_purchases f on f.customer_id=p.customer_id group by p.currency),
 spend as(select payload->>'currency' currency,payload->>'channel' channel,payload->>'category' category,sum((payload->>'amount')::numeric) amount from entities where brand_id=p_brand and kind='spend' and (payload->>'date')::date>=p_start::date and (payload->>'date')::date<p_end::date group by 1,2,3)
 select jsonb_build_object('channels',coalesce((select jsonb_agg(x) from(select * from allocated union all select * from unassigned)x),'[]'::jsonb),'revenue',coalesce((select jsonb_agg(r) from revenue r),'[]'::jsonb),'spend',coalesce((select jsonb_agg(s) from spend s),'[]'::jsonb),'lookbackDays',p_days,'periodStart',p_start,'periodEnd',p_end,'complete',true,'linearPolicy','Equal credit per distinct channel since the previous purchase within lookback','customerPolicy','New customers are explicit customer IDs whose first recorded verified purchase is in the selected period; anonymous purchases are excluded from CAC');
$$;
create or replace function public.metric_report(p_brand uuid,p_start timestamptz,p_end timestamptz,p_platform text default null,p_campaign uuid default null,p_metric text default 'impressions') returns jsonb language sql stable security definer set search_path=public as $$
 with observations as(select m.id,m.payload,m.created_at from entities m where m.brand_id=p_brand and m.kind='metrics' and (m.payload->>'observedAt')::timestamptz>=p_start and (m.payload->>'observedAt')::timestamptz<p_end and (p_platform is null or m.payload->>'platform'=p_platform) and (p_campaign is null or exists(select 1 from entities s join entities c on c.id=(s.payload->>'contentId')::uuid where s.id=(m.payload->>'postId')::uuid and c.payload->>'campaignId'=p_campaign::text))),
 latest as(select distinct on(payload->>'postId') * from observations order by payload->>'postId',(payload->>'observedAt')::timestamptz desc,id),
 metric_values as(select l.payload->>'platform' platform,j.key,(j.value::text)::numeric value from latest l cross join lateral jsonb_each(l.payload->'metrics') j where jsonb_typeof(j.value)='number'),
 totals as(select key,sum(value) value from metric_values group by key),
 daily_post as(select distinct on((payload->>'observedAt')::timestamptz::date,payload->>'postId') (payload->>'observedAt')::timestamptz::date as snapshot_day,payload from observations order by (payload->>'observedAt')::timestamptz::date,payload->>'postId',(payload->>'observedAt')::timestamptz desc),
 daily as(select snapshot_day as date,sum((payload->'metrics'->>p_metric)::numeric) value from daily_post group by snapshot_day),
 comparison as(select platform,sum(value) value from metric_values where key=p_metric group by platform)
 select jsonb_build_object('totals',coalesce((select jsonb_object_agg(key,value) from totals),'{}'::jsonb),'chart',coalesce((select jsonb_agg(d order by d.date) from daily d),'[]'::jsonb),'comparison',coalesce((select jsonb_agg(c) from comparison c),'[]'::jsonb),'latest',coalesce((select jsonb_agg(x) from(select * from latest order by created_at desc limit 50)x),'[]'::jsonb),'postCount',(select count(*) from latest),'observationCount',(select count(*) from observations),'complete',true,'periodStart',p_start,'periodEnd',p_end);
$$;
revoke all on function public.period_attribution(uuid,timestamptz,timestamptz,int),public.metric_report(uuid,timestamptz,timestamptz,text,uuid,text) from public,anon,authenticated;
grant execute on function public.period_attribution(uuid,timestamptz,timestamptz,int),public.metric_report(uuid,timestamptz,timestamptz,text,uuid,text) to service_role;
